     1→/**
     2→ * FreeLang v2 Lexer (v1 기반, 거의 변경 없음)
     3→ *
     4→ * Tokenizes FreeLang source code including:
     5→ * - v1 기본 토큰들
     6→ * - Phase 5 추가 토큰들 (INPUT, OUTPUT, INTENT)
     7→ */
     8→import { Token, TokenType, getKeyword } from './token';
     9→
    10→/**
    11→ * Lexer - Tokenizes FreeLang source code
    12→ */
    13→export class Lexer {
    14→  private input: string;
    15→  private position: number = 0;
    16→  private line: number = 1;
    17→  private column: number = 0;
    18→  private current: string = '';
    19→  private lastTokenType: TokenType = TokenType.EOF;  // Track last token for regex disambiguation
    20→
    21→  constructor(input: string) {
    22→    this.input = input;
    23→    this.readChar();
    24→  }
    25→
    26→  /**
    27→   * Read next character
    28→   */
    29→  private readChar(): void {
    30→    if (this.position >= this.input.length) {
    31→      this.current = '\0';
    32→    } else {
    33→      this.current = this.input[this.position];
    34→    }
    35→    this.position++;
    36→    this.column++;
    37→  }
    38→
    39→  /**
    40→   * Peek at next character without consuming
    41→   */
    42→  private peekChar(): string {
    43→    if (this.position >= this.input.length) {
    44→      return '\0';
    45→    }
    46→    return this.input[this.position];
    47→  }
    48→
    49→  /**
    50→   * Skip whitespace
    51→   */
    52→  private skipWhitespace(): void {
    53→    while (this.current === ' ' || this.current === '\t' || this.current === '\r') {
    54→      this.readChar();
    55→    }
    56→  }
    57→
    58→  /**
    59→   * Skip single-line comment
    60→   */
    61→  private skipComment(): void {
    62→    // Skip //
    63→    this.readChar();
    64→    this.readChar();
    65→
    66→    // Read until newline
    67→    while (this.current !== '\n' && this.current !== '\0') {
    68→      this.readChar();
    69→    }
    70→  }
    71→
    72→  /**
    73→   * Skip multi-line comment
    74→   */
    75→  private skipMultiLineComment(): void {
    76→    // Skip /*
    77→    this.readChar();
    78→    this.readChar();
    79→
    80→    while (true) {
    81→      if (this.current === '\0') {
    82→        break;
    83→      }
    84→
    85→      if (this.current === '\n') {
    86→        this.line++;
    87→        this.column = 0;
    88→      }
    89→
    90→      if (this.current === '*' && this.peekChar() === '/') {
    91→        this.readChar(); // *
    92→        this.readChar(); // /
    93→        break;
    94→      }
    95→
    96→      this.readChar();
    97→    }
    98→  }
    99→
   100→  /**
   101→   * Read identifier or keyword
   102→   */
   103→  private readIdentifier(): string {
   104→    const start = this.position - 1;
   105→    while (this.isIdentifierChar(this.current)) {
   106→      this.readChar();
   107→    }
   108→    return this.input.substring(start, this.position - 1);
   109→  }
   110→
   111→  /**
   112→   * Read number
   113→   */
   114→  private readNumber(): string {
   115→    const start = this.position - 1;
   116→
   117→    // Integer part
   118→    while (this.isDigit(this.current)) {
   119→      this.readChar();
   120→    }
   121→
   122→    // Decimal part
   123→    if (this.current === '.' && this.isDigit(this.peekChar())) {
   124→      this.readChar(); // .
   125→      while (this.isDigit(this.current)) {
   126→        this.readChar();
   127→      }
   128→    }
   129→
   130→    // Exponent
   131→    if (this.current === 'e' || this.current === 'E') {
   132→      this.readChar();
   133→      const sign: string = this.current;
   134→      if (sign === '+' || sign === '-') {
   135→        this.readChar();
   136→      }
   137→      while (this.isDigit(this.current)) {
   138→        this.readChar();
   139→      }
   140→    }
   141→
   142→    return this.input.substring(start, this.position - 1);
   143→  }
