    28→// 값을 문자열로 변환
    29→fn toString(value: any) -> string {
    30→  if typeof(value) == "string" {
    31→    return value
    32→  } else if typeof(value) == "number" {
    33→    return value.toString()
    34→  } else if typeof(value) == "boolean" {
    35→    if value == true {
    36→      return "true"
    37→    } else {
    38→      return "false"
    39→    }
    40→  } else {
    41→    return "[object]"
