    46→fn parseInt(str: string) -> int {
    47→  // 간단한 구현: 첫 숫자 부분만 추출
    48→  let result = 0
    49→  let i = 0
    50→  while i < str.length {
    51→    let ch = str[i]
    52→    if ch >= "0" && ch <= "9" {
    53→      result = result * 10 + (ch - "0")
    54→    }
    55→    i = i + 1
    56→  }
    57→  return result
    58→}
