    11→export interface UnionType {
    12→  type: 'union';
    13→  members: TypeAnnotation[];  // e.g., ['string', 'number', 'boolean']
    14→  discriminant?: string;      // Optional: discriminant property for discriminated unions
    15→}
    16→
    17→/**
    18→ * Discriminated union type
    19→ * Example: { kind: 'success'; value: T } | { kind: 'error'; error: string }
    20→ */
    21→export interface DiscriminatedUnion {
    22→  type: 'discriminated-union';
    23→  members: {
    24→    [discriminantValue: string]: TypeAnnotation;
    25→  };
    26→  discriminantProperty: string;
    27→}
    28→
    29→/**
    30→ * Type annotation (can be basic, union, conditional, or mapped)
    31→ */
    32→export type TypeAnnotation =
    33→  | string  // 'string', 'number', 'boolean', 'any', etc.
    34→  | UnionType
    35→  | DiscriminatedUnion
    36→  | { type: 'conditional' }  // ConditionalType
    37→  | { type: 'mapped'; key?: string; source?: any; value?: any; optional?: boolean; readonly?: boolean };  // MappedType
    38→
    39→/**
    40→ * Condition for type narrowing
    41→ */
    42→export interface NarrowingCondition {
    43→  type: 'typeof' | 'instanceof' | 'property-check' | 'truthy' | 'custom';
    44→  variable?: string;
    45→  targetType?: string;
    46→  property?: string;
    47→  value?: any;
    48→  predicate?: string;  // Function name for custom checks
    49→}
