    56→   * Parse union type from string
    57→   * @param typeStr Type string (e.g., "string | number | boolean")
    58→   * @returns Parsed union type
    59→   */
    60→  public static parseUnionType(typeStr: string): TypeAnnotation {
    61→    // Remove whitespace and check for union operator
    62→    const trimmed = typeStr.trim();
    63→
    64→    if (!trimmed.includes('|')) {
