    15→
    16→// ── XOR 암호화 (Zero-Dependency) ────────────────────────────
    17→
    18→function generateSalt(length: number = 32): number[] {
    19→  const salt: number[] = [];
    20→  // PRNG: xorshift32 기반 (외부 의존성 없음)
    21→  let seed = Date.now() ^ 0xDEADBEEF;
    22→  for (let i = 0; i < length; i++) {
    23→    seed ^= seed << 13;
    24→    seed ^= seed >> 17;
    25→    seed ^= seed << 5;
    26→    salt.push(Math.abs(seed) & 0xFF);
    27→  }
    28→  return salt;
    29→}
    30→
    31→function xorEncrypt(plaintext: string, salt: number[]): number[] {
    32→  const encrypted: number[] = [];
    33→  for (let i = 0; i < plaintext.length; i++) {
    34→    encrypted.push(plaintext.charCodeAt(i) ^ salt[i % salt.length]);
    35→  }
    36→  return encrypted;
    37→}
    38→
    39→function xorDecrypt(encrypted: number[], salt: number[]): string {
    40→  let result = '';
    41→  for (let i = 0; i < encrypted.length; i++) {
    42→    result += String.fromCharCode(encrypted[i] ^ salt[i % salt.length]);
    43→  }
    44→  return result;
