      this.current() === quote && this.peek() === quote;
    if (isTriple) {
      this.advance();
      this.advance();
    }

    // 문자열 콘텐츠
    while (this.pos < this.source.length) {
      const ch = this.current();

      if (ch === quote) {
        if (isTriple) {
          if (
            this.peek() === quote &&
            this.peekAhead(1) === quote
          ) {
            this.advance();
            this.advance();
            this.advance();
            break;
          }
        } else {
          this.advance();
          break;
        }
      }

      if (ch === '\\') {
        value += ch;
        this.advance();
        if (this.pos < this.source.length) {
          value += this.current();
          this.advance();
