      if (this.pos >= this.source.length) break;

      const ch = this.current();

      // 공백 스킵 (인덴트 후)
      if (ch === ' ' || ch === '\t') {
        this.advance();
        continue;
      }

      // 개행
      if (ch === '\n' || ch === '\r') {
        this.addToken(TokenType.NEWLINE, ch);
        if (ch === '\r' && this.peek() === '\n') this.advance();
        this.advance();
        this.line++;
        this.column = 1;
        this.atLineStart = true;
        continue;
      }

      // 주석 (Python)
      if (ch === '#') {
        this.skipComment();
        continue;
      }

      // 주석 (FreeLang)
      if (ch === '/' && this.peek() === '/') {
        this.skipComment();
        continue;
      }

      // 문자열
      if (ch === '"' || ch === "'") {
        this.tokenizeString();
        this.atLineStart = false;
        continue;
      }

      // f-string
      if (ch === 'f' && (this.peek() === '"' || this.peek() === "'")) {
        this.tokenizeString(true);
        this.atLineStart = false;
        continue;
      }

      // 숫자
      if (this.isDigit(ch)) {
        this.tokenizeNumber();
        this.atLineStart = false;
        continue;
      }

