 * - 문장 (Statements)
 * - 표현식 (Expressions)
 * - 타입 (Type Annotations)
 * - 데코레이터
 */

/**
 * 기본 AST 노드 인터페이스
 */
export interface ASTNode {
  type: string;
  line: number;
  column: number;
}

/**
 * 프로그램 루트
 */
export interface Program extends ASTNode {
  type: 'Program';
  body: Statement[];
}

// ==================== 문장 (Statements) ====================

export type Statement =
  | FunctionDef
  | FreeLangFunction
  | ClassDef
  | IfStatement
  | ForLoop
  | WhileLoop
  | MatchExpression
  | TryStatement
  | ReturnStatement
  | BreakStatement
  | ContinueStatement
  | PassStatement
  | AssignmentStatement
  | ExpressionStatement
  | ImportStatement
  | WithStatement;

/**
 * Python 함수 정의
 * def name(params) -> type:
 *   body
 */
export interface FunctionDef extends ASTNode {
  type: 'FunctionDef';
  name: string;
  params: Parameter[];
  returnType?: TypeAnnotation;
  body: Statement[];
  decorators: Decorator[];
  isAsync: boolean;
}

/**
 * FreeLang 함수 정의 (강타입)
 * fn name(params) -> type { body }
 */
export interface FreeLangFunction extends ASTNode {
  type: 'FreeLangFunction';
  name: string;
  params: Parameter[];
  returnType: TypeAnnotation;
  body: Statement[];
  decorators: Decorator[];
  isAsync: boolean;
}

/**
 * 클래스 정의
 * class Name(bases):
 *   body
 */
export interface ClassDef extends ASTNode {
  type: 'ClassDef';
  name: string;
  bases: Expression[];
  body: Statement[];
  decorators: Decorator[];
  isDataclass?: boolean;
}

/**
 * If 문장
 * if cond:
 *   body
 * elif cond:
 *   body
 * else:
 *   body
 */
export interface IfStatement extends ASTNode {
  type: 'IfStatement';
  condition: Expression;
  body: Statement[];
  elifParts: ElifPart[];
  elseBody?: Statement[];
}

export interface ElifPart {
  condition: Expression;
  body: Statement[];
}

/**
 * For 루프
 * for target in iter:
 *   body
 */
export interface ForLoop extends ASTNode {
  type: 'ForLoop';
  target: Expression;
  iterable: Expression;
  body: Statement[];
  elseBody?: Statement[];
}

/**
 * While 루프
 * while cond:
 *   body
 */
export interface WhileLoop extends ASTNode {
  type: 'WhileLoop';
  condition: Expression;
  body: Statement[];
  elseBody?: Statement[];
}

/**
 * Match 표현식 (FreeLang)
 * match expr {
 *   pattern1 => body1,
 *   pattern2 => body2,
 * }
 */
export interface MatchExpression extends ASTNode {
  type: 'MatchExpression';
  expr: Expression;
  arms: MatchArm[];
}

export interface MatchArm {
  pattern: Pattern;
  body: Statement[];
  guard?: Expression;
}

export type Pattern =
  | IdentifierPattern
  | LiteralPattern
  | ConstructorPattern
  | WildcardPattern;

export interface IdentifierPattern extends ASTNode {
  type: 'IdentifierPattern';
  name: string;
}

export interface LiteralPattern extends ASTNode {
  type: 'LiteralPattern';
  value: Literal;
}

export interface ConstructorPattern extends ASTNode {
  type: 'ConstructorPattern';
  constructor: string;
  fields: Pattern[];
}

export interface WildcardPattern extends ASTNode {
  type: 'WildcardPattern';
}

/**
 * Try-Except 문장
 * try:
 *   body
 * except ExceptionType as e:
 *   handler
 * finally:
 *   finallyBody
 */
export interface TryStatement extends ASTNode {
  type: 'TryStatement';
  body: Statement[];
  handlers: ExceptionHandler[];
  elseBody?: Statement[];
  finallyBody?: Statement[];
}

export interface ExceptionHandler {
  exceptionType?: Expression;
  name?: string;
  body: Statement[];
}

/**
 * Return 문장
 */
export interface ReturnStatement extends ASTNode {
  type: 'ReturnStatement';
  value?: Expression;
}

/**
 * Break 문장
 */
export interface BreakStatement extends ASTNode {
  type: 'BreakStatement';
}

/**
 * Continue 문장
 */
export interface ContinueStatement extends ASTNode {
  type: 'ContinueStatement';
}

/**
 * Pass 문장 (Python)
 */
export interface PassStatement extends ASTNode {
  type: 'PassStatement';
}

/**
 * 할당 문장
 * x = value
 * x += value
 */
export interface AssignmentStatement extends ASTNode {
  type: 'AssignmentStatement';
  target: Expression;
  operator: 'assign' | 'plus_assign' | 'minus_assign' | 'star_assign' | 'slash_assign';
  value: Expression;
}

/**
 * 표현식 문장
 * expr (그 자체로 문장)
 */
export interface ExpressionStatement extends ASTNode {
  type: 'ExpressionStatement';
  expression: Expression;
}

/**
 * Import 문장
 * import x, y
 * from x import y
 */
export interface ImportStatement extends ASTNode {
  type: 'ImportStatement';
  isFromImport: boolean;
  module?: string;
