function checkCode(code: string, level: 0 | 1 | 2 = 1): TypeCheckError[] {
  const tokens = tokenize(code);
  const ast = parse(tokens);
  return typeCheck(ast, level);
}

describe('타입 체커 - Level 0 (동적 타입)', () => {
  test('타입 없음 + 모든 연산 허용', () => {
