  });
});

describe('타입 체커 - Level 2 (정적 타입)', () => {
  test('FreeLang fn 함수는 필수 타입', () => {
    const code = `fn add(a: i64, b: i64) -> i64:
    return a + b`;

    const errors = checkCode(code, 2);
    expect(errors.filter((e) => e.severity === 'error')).toHaveLength(0);
  });

  test('제네릭 타입 검증', () => {
