  });

  test('리스트 타입 추론', () => {
    const code = `x = [1, 2, 3]`;
    const errors = checkCode(code, 1);
    // list[int]로 추론됨
  });

  test('딕셔너리 타입 추론', () => {
    const code = `x = {"a": 1, "b": 2}`;
    const errors = checkCode(code, 1);
    // dict[str, int]로 추론됨
  });

  test('함수 호출 타입 검증', () => {
    const code = `def f(x: int) -> int:
    return x

result = f("str")`;

    const errors = checkCode(code, 1);
    expect(errors.length).toBeGreaterThan(0);
  });

  test('이진 연산 타입 추론', () => {
    const code = `x = 5
y = 3.14
