  });

  test('비교 연산은 bool 반환', () => {
    const code = `x = 5 > 3
if x:
    pass`;

    const errors = checkCode(code, 1);
    expect(errors.length).toBe(0);
  });

  test('Lambda 타입 추론', () => {
    const code = `f = lambda x: x + 1`;
