    // 함수 타입으로 추론됨
  });

  test('Comprehension 타입 추론', () => {
    const code = `x = [i * 2 for i in range(10)]`;
    const errors = checkCode(code, 1);
    // list[int]로 추론됨
  });
});

describe('함수 타입', () => {
  test('async 함수 타입', () => {
    const code = `async def fetch(url: str) -> str:
    return ""`;

