    `);
  }

  /**
   * 특정 주제 도움말
   */
  private showTopicHelp(topic: string): void {
    const helps: Record<string, string> = {
      def: `함수 정의:
  def name(params) -> ReturnType:
      body

예시:
  >>> def add(a, b) -> int:
  ...     return a + b
  ...
  >>> add(2, 3)
  5`,

      class: `클래스 정의:
  class ClassName:
      body

예시:
  >>> class User:
  ...     name = "Alice"
  ...
  >>> u = User()`,

      for: `반복문:
  for variable in iterable:
      body

예시:
  >>> for i in range(5):
  ...     print(i)
  ...
  0
  1
  2
  3
  4`,

      if: `조건문:
  if condition:
      body
  elif condition:
      body
  else:
      body

예시:
  >>> x = 10
  >>> if x > 5:
  ...     print("큼")
  ... else:
  ...     print("작음")
  ...
  큼`,

      match: `패턴 매칭:
  match expression:
      pattern1 => body1
      pattern2 => body2

예시:
  >>> match status:
  ...     200 => print("OK")
  ...     404 => print("Not found")
  ...
  OK`,

      async: `비동기 함수:
  async def name(params):
      await expression

예시:
  >>> async def fetch(url):
  ...     data = await get(url)
  ...     return data`,

      result: `Result 타입 (오류 처리):
  def f() -> Result[T, E]:
      return Ok(value) or Err(error)

예시:
  >>> def parse(s: str) -> Result[int, str]:
  ...     try:
  ...         return Ok(int(s))
  ...     except:
  ...         return Err("parse failed")`,
    };

    const help = helps[topic.toLowerCase()];
    if (help) {
      console.log(help);
    } else {
      console.log(`알 수 없는 주제: ${topic}`);
      console.log('다음을 시도해보세요: help(def), help(class), help(for)');
    }
  }
}

/**
 * REPL 시작 함수
 */
export function startREPL(): void {
  const session = new REPLSession();
  session.start();
}

// CLI 실행
if (require.main === module) {
  startREPL();
}

