    21→
    22→/**
    23→ * 프로그램 루트
    24→ */
    25→export interface Program extends ASTNode {
    26→  type: 'Program';
    27→  body: Statement[];
    28→}
    29→
    30→// ==================== 문장 (Statements) ====================
    31→
    32→export type Statement =
    33→  | FunctionDef
    34→  | FreeLangFunction
    35→  | ClassDef
    36→  | IfStatement
    37→  | ForLoop
    38→  | WhileLoop
    39→  | TryStatement
