    48→
    49→/**
    50→ * Python 함수 정의
    51→ * def name(params) -> type:
    52→ *   body
    53→ */
    54→export interface FunctionDef extends ASTNode {
    55→  type: 'FunctionDef';
    56→  name: string;
    57→  params: Parameter[];
    58→  returnType?: TypeAnnotation;
    59→  body: Statement[];
    60→  decorators: Decorator[];
    61→  isAsync: boolean;
    62→}
    63→
    64→/**
    65→ * FreeLang 함수 정의 (강타입)
    66→ * fn name(params) -> type { body }
    67→ */
    68→export interface FreeLangFunction extends ASTNode {
    69→  type: 'FreeLangFunction';
    70→  name: string;
    71→  params: Parameter[];
    72→  returnType: TypeAnnotation;
    73→  body: Statement[];
    74→  decorators: Decorator[];
    75→  isAsync: boolean;
    76→}
    77→
    78→/**
    79→ * 클래스 정의
