    89→  isDataclass?: boolean;
    90→}
    91→
    92→/**
    93→ * If 문장
    94→ * if cond:
    95→ *   body
    96→ * elif cond:
    97→ *   body
    98→ * else:
    99→ *   body
   100→ */
   101→export interface IfStatement extends ASTNode {
   102→  type: 'IfStatement';
