export interface ASTNode {
  type: string;
  line: number;
  column: number;
}

/**
 * 프로그램 루트
 */
export interface Program extends ASTNode {
  type: 'Program';
  body: Statement[];
}

// ==================== 문장 (Statements) ====================

export type Statement =
  | FunctionDef
  | FreeLangFunction
  | ClassDef
  | IfStatement
  | ForLoop
  | WhileLoop
  | TryStatement
  | ReturnStatement
  | BreakStatement
  | ContinueStatement
  | PassStatement
  | AssignmentStatement
  | ExpressionStatement
  | ImportStatement
  | WithStatement;

/**
 * Python 함수 정의
 * def name(params) -> type:
 *   body
 */
export interface FunctionDef extends ASTNode {
  type: 'FunctionDef';
  name: string;
  params: Parameter[];
  returnType?: TypeAnnotation;
  body: Statement[];
  decorators: Decorator[];
  isAsync: boolean;
}

/**
 * FreeLang 함수 정의 (강타입)
 * fn name(params) -> type { body }
 */
export interface FreeLangFunction extends ASTNode {
  type: 'FreeLangFunction';
  name: string;
  params: Parameter[];
  returnType: TypeAnnotation;
  body: Statement[];
  decorators: Decorator[];
  isAsync: boolean;
}

/**
 * 클래스 정의
 * class Name(bases):
 *   body
 */
export interface ClassDef extends ASTNode {
  type: 'ClassDef';
  name: string;
  bases: Expression[];
  body: Statement[];
  decorators: Decorator[];
  isDataclass?: boolean;
}

/**
 * If 문장
 * if cond:
 *   body
 * elif cond:
 *   body
 * else:
 *   body
 */
export interface IfStatement extends ASTNode {
  type: 'IfStatement';
  condition: Expression;
  body: Statement[];
  elifParts: ElifPart[];
  elseBody?: Statement[];
}

export interface ElifPart {
  condition: Expression;
  body: Statement[];
}

/**
 * For 루프
 * for target in iter:
 *   body
 */
export interface ForLoop extends ASTNode {
  type: 'ForLoop';
  target: Expression;
  iterable: Expression;
  body: Statement[];
  elseBody?: Statement[];
}

/**
 * While 루프
 * while cond:
 *   body
 */
export interface WhileLoop extends ASTNode {
  type: 'WhileLoop';
  condition: Expression;
  body: Statement[];
  elseBody?: Statement[];
}

/**
 * Match 표현식 (FreeLang)
 * match expr {
 *   pattern1 => body1,
 *   pattern2 => body2,
 * }
 */
export interface MatchExpression extends ASTNode {
  type: 'MatchExpression';
  expr: Expression;
  arms: MatchArm[];
}

