/**
 * 함수 호출 컴파일
 */
private compileFunctionCall(expr: any): number {
  const resultReg = this.allocRegister();
  const funcReg = this.compileExpression(expr.func);
  const args = expr.args || [];
  const argRegs: number[] = [];

  for (const arg of args) {
    argRegs.push(this.compileExpression(arg));
  }

  this.builder.emit(Opcode.CALL, [resultReg, funcReg, argRegs.length, ...argRegs]);

  this.freeRegister(funcReg);
  for (const argReg of argRegs) {
    this.freeRegister(argReg);
  }

  return resultReg;
}

