    // 실제로는 MOVE 명령어를 추가하거나 이전 단계에서 처리해야 함
    // 지금은 간단하게 LOAD_CONST로 값을 로드
    if (actualArg.type === 'Literal') {
      const constIdx = this.builder.addConstant(actualArg.value);
      this.builder.emit(Opcode.LOAD_CONST, [argReg, constIdx]);
    } else {
      // 더 일반적인 경우: 이미 계산된 레지스터의 값을 복사
      // ADD로 0을 더해서 값을 복사하는 트릭 사용
      const zeroIdx = this.builder.addConstant(0);
      this.builder.emit(Opcode.LOAD_CONST, [this.allocRegister(), zeroIdx]);
      this.builder.emit(Opcode.ADD, [argReg, argValueReg, this.nextRegister - 1]);
      this.freeRegister(this.nextRegister - 1);
    }
  }

  // CALL: r[resultReg] = call(r[funcReg], argCount)
  // 실제 인자는 r[resultReg + 1], r[resultReg + 2], ... 에 위치
  this.builder.emit(Opcode.CALL, [resultReg, funcReg, args.length]);

  this.freeRegister(funcReg);

  return resultReg;
}

