    this.builder.emit(Opcode.LOAD_GLOBAL, [resultReg, symbol.index]);
  } else {
    // 정의되지 않은 변수는 자동으로 전역 함수로 간주 (런타임에 해석됨)
    // 예: print, len, range 등의 내장 함수
    const globalIdx = this.builder.addGlobal(name);
    this.builder.emit(Opcode.LOAD_GLOBAL, [resultReg, globalIdx]);
    this.registerSymbol(name, true, undefined, globalIdx);
  }

  return resultReg;
}

