// 함수 호출 인자를 전용 영역에 배치 (r[200]부터 시작)
// 버그 수정: 각 인자를 먼저 일반 영역에서 컴파일하고 결과를 함수 인자 영역으로 복사
const argValueRegs: number[] = [];
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
  const actualArg = arg.value || arg;
  // 인자 표현식을 컴파일하면 일반 레지스터(r0-r199)에 결과가 저장됨
  const argValueReg = this.compileExpression(actualArg);
  argValueRegs.push(argValueReg);
}

// 각 인자 값을 함수 호출 전용 영역으로 복사
for (let i = 0; i < argValueRegs.length; i++) {
  const argValueReg = argValueRegs[i];
  const argReg = 200 + i; // 전용 영역: r[200], r[201], ...
  // 값 복사: argReg = argValueReg + 0
  const zeroIdx = this.builder.addConstant(0);
  const zeroReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_CONST, [zeroReg, zeroIdx]);
  this.builder.emit(Opcode.ADD, [argReg, argValueReg, zeroReg]);
  this.freeRegister(argValueReg);
  this.freeRegister(zeroReg);
}

