  const actualArg = arg.value || arg;

  // 임시: 각 인자를 일반 영역에서 먼저 컴파일
  const argValueReg = this.compileExpression(actualArg);
  // 그 값을 함수 호출 전용 영역으로 복사 (직접 할당하지 않음)
  // 복사 방법: ADD를 사용하되 불필요한 로드 명령어 제거
