  // 지금은: 단순하게 결과 레지스터를 사용하고 VM에서 처리하도록 함
  // (실제로는 r[argValueReg]가 r[200+i]처럼 동작하도록 VM 수정 필요)
  this.freeRegister(argValueReg);
}

