// 함수 호출 인자를 전용 영역에 배치 (r[200]부터 시작)
// 각 인자를 컴파일하면서 레지스터를 직접 함수 호출 영역에 할당
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
  const actualArg = arg.value || arg;

  // 임시: 각 인자를 일반 영역에서 먼저 컴파일
  const argValueReg = this.compileExpression(actualArg);
  // 그 값을 함수 호출 전용 영역으로 복사 (직접 할당하지 않음)
  // 복사 방법: ADD를 사용하되 불필요한 로드 명령어 제거
  // 더 간단하게: 컴파일러가 r[200+]에 직접 컴파일하도록 변경 필요
  // 지금은: 단순하게 결과 레지스터를 사용하고 VM에서 처리하도록 함
  // (실제로는 r[argValueReg]가 r[200+i]처럼 동작하도록 VM 수정 필요)
  this.freeRegister(argValueReg);
}

