  const arg = args[i];
  // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
  const actualArg = arg.value || arg;

  // 각 인자를 컴파일하면 자동으로 레지스터가 할당됨
  const argReg = this.compileExpression(actualArg);
  argRegs.push(argReg);
}

