// 함수 호출 인자를 r[200]부터 순차적으로 배치
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
  const actualArg = arg.value || arg;

  // 각 인자를 컴파일하면 일반 레지스터(0-199)에 결과가 저장됨
  const argValueReg = this.compileExpression(actualArg);

  // 그 값을 함수 호출 전용 영역(r200+)으로 복사
  const argCallReg = 200 + i;
  // 복사: r[argCallReg] = r[argValueReg] + 0
  const zeroIdx = this.builder.addConstant(0);
  const zeroReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_CONST, [zeroReg, zeroIdx]);
  this.builder.emit(Opcode.ADD, [argCallReg, argValueReg, zeroReg]);

  // 사용한 레지스터 해제
  this.freeRegister(argValueReg);
  this.freeRegister(zeroReg);
}

