// 가장 간단한 방법: 각 인자를 먼저 컴파일한 후, 결과를 함수 호출 영역에 직접 배치
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
  const actualArg = arg.value || arg;

  // 각 인자를 컴파일하면 일반 레지스터(0-199)에 결과가 저장됨
  const argValueReg = this.compileExpression(actualArg);
  // argValueReg의 값을 r[200+i]로 직접 복사 (단순하게)
  // 방법: ADD [200+i, argValueReg, 0]
  const zeroIdx = this.builder.addConstant(0);
  this.builder.emit(Opcode.LOAD_CONST, [200 + i, zeroIdx]);
  // 이건 잘못됨. 다시 생각해보니 단순 할당이 필요함.
}

