  const actualArg = arg.value || arg;

  // 각 인자를 컴파일하면 일반 레지스터(0-199)에 결과가 저장됨
  const argValueReg = this.compileExpression(actualArg);
  argValueRegs.push(argValueReg);
}

// 계산한 인자 값들을 함수 호출 전용 영역(r200+)으로 복사
for (let i = 0; i < argValueRegs.length; i++) {
  const srcReg = argValueRegs[i];
  const dstReg = 200 + i;
  // 간단한 복사: 임시 0 상수를 사용하지 말고 직접 할당
  // ADD [dstReg, srcReg, 0] 형태인데, 0을 로드할 필요 없이 그냥 작성
  this.builder.emit(Opcode.ADD, [dstReg, srcReg, 0]); // 바로 0 사용
  this.freeRegister(srcReg);
}

