private compileFunctionCall(expr: any): number {
  const resultReg = this.allocRegister();

  // AST에서 함수는 'function' 필드에 있음
  const funcNode = expr.function || expr.func;
  if (!funcNode) {
    this.builder.emit(Opcode.LOAD_NONE, [resultReg]);
    return resultReg;
  }

  const funcReg = this.compileExpression(funcNode);
  const args = expr.args || [];

  // 함수 호출 인자를 resultReg 다음부터 배치 (r[resultReg+1], r[resultReg+2], ...)
  // 이것은 registerAllocator를 신뢰하지 않는 간단한 방식
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    // Parser에서 arg.value 형태로 감싸질 수 있으므로 언래핑
    const actualArg = arg.value || arg;

    // 각 인자를 컴파일
    const argValueReg = this.compileExpression(actualArg);

    // 인자를 지정된 위치(resultReg + 1 + i)로 이동
    // 여기서 주의: registerAllocator가 관여하지 않으므로 수동으로 레지스터 관리
    const argDestReg = resultReg + 1 + i;
    // 만약 argValueReg != argDestReg라면 이동이 필요함
    if (argValueReg !== argDestReg) {
      // 간단한 이동: ADD [dst, src, 0] 형태로 복사
      // 하지만 0을 상수로 로드하면 다시 registerAllocator가 관여함
      // 더 간단하게: arguments are placed in registers starting from resultReg+1
      // 그냥 ARG ValueReg을 인자 위치로 사용하도록 VM 수정이 필요
      // 지금은: 간단하게 resultReg + 1부터 순차적으로 배치되도록 강제
      this.builder.emit(Opcode.ADD, [argDestReg, argValueReg, 0]);
    }
    this.freeRegister(argValueReg);
  }

  // CALL: r[resultReg] = call(r[funcReg], argCount)
  this.builder.emit(Opcode.CALL, [resultReg, funcReg, args.length]);
  this.freeRegister(funcReg);

  return resultReg;
}

