print(add(3, 4))`
  },
  {
    name: 'for-in 루프',
    code: `for i in range(3):
    print(i)`
  },
  {
    name: '리스트 컴프리헨션',
    code: `squares = [x * x for x in range(5)]
print(squares)`
  },
  {
    name: '조건문 (if-else)',
    code: `x = 10
if x > 5:
    print("크다")
else:
    print("작다")`
  },
  {
    name: '리스트 연산',
    code: `arr = [1, 2, 3]
