private compileForLoop(stmt: any): void {
  // 반복 대상(iterable) 컴파일: range(3) → [0,1,2]
  const iterReg = this.compileExpression(stmt.iterable);
  const targetName = stmt.target.type === 'Identifier' ? stmt.target.name : null;

  if (!targetName) {
    this.freeRegister(iterReg);
    return;
  }

  // 루프 제어 변수 준비
  const indexReg = this.allocRegister();      // 인덱스: 0, 1, 2, ...
  const lenReg = this.allocRegister();        // 배열 길이
  const itemReg = this.allocRegister();       // 현재 요소
  const targetReg = this.allocRegister();     // target 변수

  // 초기화: indexReg = 0
  const zeroIdx = this.builder.addConstant(0);
  this.builder.emit(Opcode.LOAD_CONST, [indexReg, zeroIdx]);

  // 배열 길이 계산: len(iterable)
  // len 함수를 호출하거나, 배열 길이를 직접 사용
  // 간단하게: 배열의 length 속성으로부터 얻음
  // (JavaScript의 배열이므로 .length가 있음)
  // 하지만 IR에서는 이것을 직접 지원하지 않으므로,
  // 배열이 range 결과라면, 범위를 이미 알 수 있음
  // 대신: 배열을 순회하는 다른 방식 사용

  // 더 간단한 방식: 배열 반복을 위해 반복 불가능한 상황 체크
  // 현재는 배열만 지원하므로, 배열의 길이를 동적으로 얻음
  const lenCallReg = this.allocRegister();
  const lenGlobalReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_GLOBAL, [lenGlobalReg, 'len']);
  this.builder.emit(Opcode.CALL, [lenReg, lenGlobalReg, 1, iterReg]);
  this.freeRegister(lenGlobalReg);
  this.freeRegister(lenCallReg);

  // 루프 시작 오프셋 저장
  const loopStartOffset = this.builder.getCurrentOffset();
  this.loopStack.push(loopStartOffset);

  // 조건 체크: index < len
  const condReg = this.allocRegister();
  this.builder.emit(Opcode.LT, [condReg, indexReg, lenReg]);

  // 거짓이면 루프 탈출 (offset은 나중에 패치)
  const jumpIfFalseIdx = this.builder.getCurrentOffset();
  this.builder.emit(Opcode.JUMP_IF_FALSE, [condReg, 0]);

  // 현재 요소 로드: item = iterable[index]
  this.builder.emit(Opcode.INDEX_GET, [itemReg, iterReg, indexReg]);

  // 타겟 변수에 할당
  const oldSymbol = this.lookupSymbol(targetName);
  this.registerSymbol(targetName, false, targetReg);
  this.builder.emit(Opcode.STORE_FAST, [targetReg, itemReg]);

  // 루프 본문 컴파일
  for (const s of stmt.body) {
    this.compileStatement(s);
  }

  // 심볼 복구
  if (oldSymbol) {
    this.symbols.set(targetName, oldSymbol);
  } else {
    this.symbols.delete(targetName);
  }

  // 인덱스 증가: index = index + 1
  const oneIdx = this.builder.addConstant(1);
  const oneReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_CONST, [oneReg, oneIdx]);
  this.builder.emit(Opcode.ADD, [indexReg, indexReg, oneReg]);
  this.freeRegister(oneReg);

  // 루프 시작으로 점프
  this.builder.emit(Opcode.JUMP, [loopStartOffset]);

  // 루프 탈출 지점 패치
  this.builder.code[jumpIfFalseIdx].args[1] = this.builder.getCurrentOffset();

  this.loopStack.pop();

  // 사용한 레지스터 해제
  this.freeRegister(indexReg);
  this.freeRegister(lenReg);
  this.freeRegister(itemReg);
  this.freeRegister(targetReg);
  this.freeRegister(condReg);
  this.freeRegister(iterReg);
}

