const oldSymbol = this.lookupSymbol(targetName);
this.registerSymbol(targetName, false, targetReg);

// 현재 요소를 target 레지스터로 복사
// ADD를 사용하여 복사: targetReg = itemReg + 0
const zeroRegIdx = this.builder.addConstant(0);
const zeroRegIdxReg = this.allocRegister();
this.builder.emit(Opcode.LOAD_CONST, [zeroRegIdxReg, zeroRegIdx]);
this.builder.emit(Opcode.ADD, [targetReg, itemReg, zeroRegIdxReg]);
this.freeRegister(zeroRegIdxReg);

